import {sql} from 'drizzle-orm'
import {
  index,
  integer,
  numeric,
  pgEnum,
  pgTable,
  primaryKey,
  text,
  timestamp,
  uuid,
} from 'drizzle-orm/pg-core'

/**
 * Primary keys are uuid v7, generated by Postgres 18's native uuidv7().
 *
 * v7 embeds a timestamp in its high bits, so ids sort chronologically. That is
 * what lets every "newest first" query be `ORDER BY id DESC` with keyset
 * pagination — no OFFSET, which drifts when rows are inserted mid-scroll, and
 * no separate sequence column.
 */
const primaryId = () => uuid('id').primaryKey().default(sql`uuidv7()`)

const createdAt = () =>
  timestamp('created_at', {withTimezone: true}).notNull().defaultNow()

/**
 * Units a recipe ingredient can be measured in. Entered through a select, never
 * free text, so this list is the only thing that can end up in the column.
 * Deliberately a little generous: adding a value later is a migration.
 */
export const unitEnum = pgEnum('unit', [
  'g',
  'ml',
  'unidad',
  'cucharada',
  'cucharadita',
  'taza',
  'pizca',
])

/**
 * `boundary` is not a message — it is a marker written when the user taps
 * "Empezar de nuevo". The send query reads the last N rows *after* the most
 * recent boundary, which is how a context reset works without deleting
 * anything or needing a second table.
 */
export const messageRoleEnum = pgEnum('message_role', [
  'user',
  'assistant',
  'boundary',
])

export const recipes = pgTable('recipes', {
  id: primaryId(),
  // Unique, like every other name in this schema. Two recipes with the same
  // name are a double-save rather than two dishes — if they really are
  // different, they need different names to be told apart in a list anyway.
  name: text('name').notNull().unique(),
  // Minutes, not a formatted string: the list sorts and filters on it.
  prepTimeMinutes: integer('prep_time_minutes'),
  // Ordered steps and reference links. Arrays rather than tables because
  // nothing ever queries an individual step — they are read and written whole.
  instructions: text('instructions').array().notNull().default([]),
  links: text('links').array().notNull().default([]),
  // Derived from a YouTube link when there is one, pasted otherwise. The app
  // stores no image files; this is always a URL.
  imageUrl: text('image_url'),
  createdAt: createdAt(),
})

export const labelGroups = pgTable('label_groups', {
  id: primaryId(),
  name: text('name').notNull().unique(),
})

export const labels = pgTable(
  'labels',
  {
    id: primaryId(),
    // Unique across the whole table, not per group. Two labels sharing a name
    // are indistinguishable once they are chips on a recipe — the group they
    // belong to is not rendered there — so a duplicate name is a data-entry
    // mistake rather than a use case, whichever group it lands in.
    name: text('name').notNull().unique(),
    // Free hex, chosen by the user. No text colour is stored alongside it —
    // chip text is computed from this value's luminance at render time, so a
    // picked colour cannot end up unreadable. See lib/color.ts.
    color: text('color').notNull(),
    labelGroupId: uuid('label_group_id')
      .notNull()
      .references(() => labelGroups.id, {onDelete: 'cascade'}),
  },
  t => [index('labels_group_idx').on(t.labelGroupId)],
)

export const recipeLabels = pgTable(
  'recipe_labels',
  {
    recipeId: uuid('recipe_id')
      .notNull()
      .references(() => recipes.id, {onDelete: 'cascade'}),
    labelId: uuid('label_id')
      .notNull()
      .references(() => labels.id, {onDelete: 'cascade'}),
  },
  t => [
    primaryKey({columns: [t.recipeId, t.labelId]}),
    // The composite key already covers recipe → labels. This covers the other
    // direction, which is what the "filter by label" chips actually query.
    index('recipe_labels_label_idx').on(t.labelId),
  ],
)

export const ingredients = pgTable('ingredients', {
  id: primaryId(),
  name: text('name').notNull().unique(),
  photoUrl: text('photo_url'),
})

export const recipeIngredients = pgTable(
  'recipe_ingredients',
  {
    id: primaryId(),
    recipeId: uuid('recipe_id')
      .notNull()
      .references(() => recipes.id, {onDelete: 'cascade'}),
    ingredientId: uuid('ingredient_id')
      .notNull()
      .references(() => ingredients.id, {onDelete: 'restrict'}),
    unit: unitEnum('unit').notNull(),
    // Nullable on purpose: "sal, al gusto" has no number.
    quantity: numeric('quantity', {precision: 10, scale: 2, mode: 'number'}),
  },
  t => [index('recipe_ingredients_recipe_idx').on(t.recipeId)],
)

export const dinners = pgTable(
  'dinners',
  {
    id: primaryId(),
    // Separate from created_at because a dinner can be logged after the fact,
    // which is also why this needs its own index rather than riding on the id.
    eatenAt: timestamp('eaten_at', {withTimezone: true}).notNull().defaultNow(),
    notes: text('notes'),
    createdAt: createdAt(),
  },
  t => [index('dinners_eaten_at_idx').on(t.eatenAt.desc())],
)

export const dinnerRecipes = pgTable(
  'dinner_recipes',
  {
    dinnerId: uuid('dinner_id')
      .notNull()
      .references(() => dinners.id, {onDelete: 'cascade'}),
    recipeId: uuid('recipe_id')
      .notNull()
      .references(() => recipes.id, {onDelete: 'cascade'}),
  },
  t => [
    primaryKey({columns: [t.dinnerId, t.recipeId]}),
    // Answers "when did we last eat this?" from a recipe page.
    index('dinner_recipes_recipe_idx').on(t.recipeId),
  ],
)

/**
 * What is in the kitchen right now. Keyed by ingredient rather than carrying
 * its own id: an ingredient is either in the pantry or it is not, so a second
 * row for the same ingredient would be a bug rather than a use case. This is
 * the input for "qué cocino con lo que tengo".
 */
export const pantry = pgTable('pantry', {
  ingredientId: uuid('ingredient_id')
    .primaryKey()
    .references(() => ingredients.id, {onDelete: 'cascade'}),
  quantity: numeric('quantity', {precision: 10, scale: 2, mode: 'number'}),
  unit: unitEnum('unit'),
  updatedAt: timestamp('updated_at', {withTimezone: true})
    .notNull()
    .defaultNow(),
})

export const messages = pgTable('messages', {
  id: primaryId(),
  role: messageRoleEnum('role').notNull(),
  content: text('content').notNull(),
  createdAt: createdAt(),
})

export type Recipe = typeof recipes.$inferSelect
export type NewRecipe = typeof recipes.$inferInsert
export type Label = typeof labels.$inferSelect
export type LabelGroup = typeof labelGroups.$inferSelect
export type Ingredient = typeof ingredients.$inferSelect
export type Dinner = typeof dinners.$inferSelect
export type PantryEntry = typeof pantry.$inferSelect
export type Message = typeof messages.$inferSelect
export type Unit = (typeof unitEnum.enumValues)[number]
export type MessageRole = (typeof messageRoleEnum.enumValues)[number]
